cat > /app/output/gen.py <<'PY'
import sys, os, json, shlex
import numpy as np
from PIL import Image
sys.path.insert(0, '/opt/tools')
from rcb_client import Robot

r = Robot()
spec = r.spec()
dt = spec['control_dt']
cams = list(spec['cameras'])
out = '/app/output/live'
os.makedirs(out, exist_ok=True)
seq = 0
last = None

def record(res, label):
    global seq, last
    seq += 1
    last = res
    d = f'{out}/{seq:03d}_{label}'
    res.save(d)
    p = res.meta['proprio']['now']
    lay = res.meta['proprio']['layout']
    q = dict(zip(lay, p))
    print(json.dumps({'seq':seq,'label':label,'tcp':[q['tcp_x'],q['tcp_y'],q['tcp_z']], 'mocap':[q['mocap_x'],q['mocap_y'],q['mocap_z']], 'opening':q['gripper_opening'],'steps':res.meta['control_steps'],'left_s':res.meta['time_left_s'],'done':res.meta['done']}),flush=True)
    return q

def see(label):
    return record(r.get_obs(cameras=cams, include_depth=True, video='frames'),label)

def act(a, label):
    a=np.asarray(a,dtype=np.float64)
    if a.ndim==1:a=a[None]
    print('ACTION',label,a.shape,'first',a[0].tolist(),'last',a[-1].tolist(),flush=True)
    return record(r.submit('ee_delta',a,dt=dt,cameras=cams,include_depth=True,video='frames',video_fps=10,note=label),label)

def move(pos, grip, label, speed=.8, settle=10):
    q=see(label+'_before')
    current=np.array([q['mocap_x'],q['mocap_y'],q['mocap_z']])
    pos=np.asarray(pos,dtype=float)
    delta=pos-current
    n=max(1,int(np.ceil(np.max(np.abs(delta)) / (0.01*speed))))
    a=np.tile(np.r_[delta/(0.01*n),grip],(n,1))
    if settle:a=np.vstack((a,np.tile([0.,0.,0.,grip],(settle,1))))
    return act(a,label)

def hold(n,grip,label):
    return act(np.tile([0.,0.,0.,grip],(n,1)),label)

print('READY',flush=True)
see('start')
while True:
    try: line=input('cmd> ')
    except EOFError: break
    if not line: continue
    t=shlex.split(line)
    try:
        if t[0]=='see':see(t[1] if len(t)>1 else 'see')
        elif t[0]=='move':move([float(v) for v in t[1:4]],float(t[4]),t[5] if len(t)>5 else 'move',float(t[6]) if len(t)>6 else .8)
        elif t[0]=='hold':hold(int(t[1]),float(t[2]),t[3] if len(t)>3 else 'hold')
        elif t[0]=='act':act(np.tile([float(v) for v in t[1:5]],(int(t[5]),1)),t[6] if len(t)>6 else 'act')
        elif t[0]=='status':print(json.dumps(r.status(),indent=2),flush=True)
        elif t[0]=='quit':break
        else:print('unknown',flush=True)
    except Exception as e:
        print('ERROR',repr(e),flush=True)
PY
python -u /app/output/gen.py
